function localizedReview(input){const lang=I();if(lang==='de')return null;const R=root.PizzaReview,r=R.normalize(input),parts=[];if(r.mode&&r.length!=='short')parts.push(r.tone==='personal'?starts[lang][r.mode][r.variant]:({en:'Order type: ',it:'Tipo di ordine: ',es:'Tipo de pedido: ',fr:'Type de commande : '}[lang]+modeNames[lang][r.mode]+'.'));if(r.dish.trim())parts.push(({en:'I ordered: ',it:'Ho ordinato: ',es:'Pedí: ',fr:'J’ai commandé : '}[lang]+r.dish.trim()+'.').replace(/([.!?])\.$/,'$1'));for(const a of R.available(r.mode)){const choice=a.choices.find(c=>c.id===r.selected[a.id]);if(!choice)continue;const detail=a.followup?.when===choice.id?a.followup.choices.find(c=>c.id===r.details[a.id]):null;const de=(detail||choice).text;parts.push(reviewText[de]?.[lang]||de);}if(r.notes.trim())parts.push(r.notes.trim());if(r.own!==null){const n=r.own.toFixed(1).replace('.',lang==='en'?'.':',');parts.push(({en:r.tone==='personal'?'My personal rating: ':'Overall rating: ',it:r.tone==='personal'?'La mia valutazione personale: ':'Valutazione complessiva: ',es:r.tone==='personal'?'Mi valoración personal: ':'Valoración general: ',fr:r.tone==='personal'?'Ma note personnelle : ':'Note globale : '}[lang])+n+({en:' out of 10.',it:' su 10.',es:' de 10.',fr:' sur 10.'}[lang]));}if(r.returnVisit){const group=!r.mode?'none':r.mode==='dinein'?'dinein':'other';parts.push(returnText[lang][group][r.returnVisit]);}return parts.join(r.length==='detailed'?'\n\n':' ');}
function installReview(){if(!root.PizzaReview||root.PizzaReview.__fullI18n)return;const previous=root.PizzaReview.generate.bind(root.PizzaReview);root.PizzaReview.generate=input=>I()==='de'?previous(input):localizedReview(input);root.PizzaReview.__fullI18n=true;}

const modelCopy={
 en:{selected:'SELECTED OFFLINE MODEL',conversion:'ONNX conversion by Xenova',download:'additional download',device:'On your device',noapi:'Photo analysis without an AI API key',why:'Why is a model downloaded?',whyP:'The model contains learned image and text patterns that PizzaScan uses to compare your pizza photo with descriptions. This lets the photo analysis run on your smartphone without sending the photo to an AI service. Your photos are not used to train a new model.',extra:'In addition to the APK:',extraP:'The model files are not included in the APK. Only after your confirmation does PizzaScan download the selected model from Hugging Face and save it in the private persistent app storage on this device. The map can be used without a model.',disc:'Photo-analysis disclaimer:',discP:'The experimental AI photo index from 0.1 to 10.0 estimates visible characteristics; it is not a reliable quality measurement. Taste, smell, temperature, allergens, hygiene and food safety cannot be determined from it. The 100 perspectives are simulated weightings of the same 25 values—not 100 real experts or independent assessments.',dls:'Download, storage and costs',dlP:'The first download for {model} is approximately {mb} MB including small companion files. The size may change with model versions. Wi-Fi is recommended; mobile data may incur charges. PizzaScan charges no model-usage fee and requires no AI subscription, provider account or API key.',storeP:'Keep several hundred MB of storage free in addition to the app. Each additional model has its own download; all three together are about 530 MB. Downloading and inference also require working memory. Duration, battery use and device temperature depend on your phone. You can cancel an active process; files that were completely stored can be reused.',offline:'What works offline afterwards?',offlineP:'After a complete download, photo analysis works without an internet connection. The model is stored in PizzaScan’s private persistent app storage and is reused after app restarts and normal cache clearing. Switching to a model that has not yet been installed requires another confirmed download.',deleteP:'The stored model is removed only when you use “Remove downloaded models”, clear PizzaScan’s app data in Android or uninstall the app. A normal cache cleanup does not remove this persistent model storage.',mapP:'“Offline” refers to photo analysis. New map tiles, restaurant searches, current place data and Google Maps still need an internet connection. PizzaScan does not silently fall back to cloud AI if local analysis fails.',privacy:'Privacy and limitations in detail',privacyP:'During model download, Hugging Face and its delivery servers receive technically necessary connection data such as your IP address and the requested model files. Your photo and review are not sent with the model request. Photos and results remain local in PizzaScan unless you explicitly export, copy or share them.',limitsP:'CLIP and SigLIP are general image-language models, not certified pizza judges. They compare the photo with English descriptions for each category. Lighting, perspective, sharpness, pizza style and learned model biases can affect results. Decimal places do not imply that level of measurement precision, and different models may produce different scores.',ownP:'Your personal rating remains separate. Review a Google Maps draft before publishing and base statements about taste or service on your actual experience. PizzaScan never publishes a review automatically.',origin:'Model name and origin',originP:'PizzaScan uses {model} by {dev} in the space-saving q8 ONNX version by Xenova. Local execution uses Transformers.js and ONNX Runtime. CLIP means “Contrastive Language–Image Pre-training”; SigLIP means “Sigmoid Loss for Language–Image Pre-training”.',source:'Model source:'},
 it:{selected:'MODELLO OFFLINE SELEZIONATO',conversion:'Conversione ONNX di Xenova',download:'download aggiuntivo',device:'Sul tuo dispositivo',noapi:'Analisi foto senza chiave API IA',why:'Perché viene scaricato un modello?',whyP:'Il modello contiene schemi visivi e testuali già appresi che PizzaScan usa per confrontare la foto della pizza con descrizioni. In questo modo l’analisi può essere eseguita sullo smartphone senza inviare la foto a un servizio IA. Le tue foto non vengono usate per addestrare un nuovo modello.',extra:'Oltre all’APK:',extraP:'I file del modello non sono inclusi nell’APK. Solo dopo la tua conferma PizzaScan scarica da Hugging Face il modello scelto e lo salva nella memoria privata persistente dell’app su questo dispositivo. La mappa può essere usata anche senza modello.',disc:'Disclaimer sull’analisi foto:',discP:'L’indice IA sperimentale da 0,1 a 10,0 stima caratteristiche visibili e non è una misurazione affidabile della qualità. Gusto, odore, temperatura, allergeni, igiene e sicurezza alimentare non possono essere determinati dalla foto. Le 100 prospettive sono ponderazioni simulate degli stessi 25 valori, non 100 esperti reali o valutazioni indipendenti.',dls:'Download, memoria e costi',dlP:'Il primo download di {model} è di circa {mb} MB incluse piccole risorse accessorie. La dimensione può cambiare con le versioni del modello. Si consiglia il Wi-Fi; i dati mobili possono comportare costi. PizzaScan non applica costi d’uso del modello e non richiede abbonamento IA, account del fornitore o chiave API.',storeP:'Mantieni libere alcune centinaia di MB oltre allo spazio dell’app. Ogni modello aggiuntivo richiede il proprio download; tutti e tre insieme occupano circa 530 MB. Download e analisi richiedono anche memoria di lavoro. Durata, consumo della batteria e temperatura dipendono dal dispositivo. Puoi interrompere il processo; i file già salvati completamente possono essere riutilizzati.',offline:'Cosa funziona offline dopo?',offlineP:'Dopo un download completo, l’analisi foto funziona senza Internet. Il modello viene salvato nella memoria privata persistente di PizzaScan e riutilizzato dopo il riavvio dell’app e dopo una normale pulizia della cache. Il passaggio a un modello non ancora installato richiede un nuovo download confermato.',deleteP:'Il modello viene rimosso solo tramite “Rimuovi modelli scaricati”, cancellando i dati dell’app PizzaScan in Android o disinstallando l’app. Una normale pulizia della cache non rimuove questa memoria persistente.',mapP:'“Offline” si riferisce all’analisi foto. Nuove tessere della mappa, ricerca ristoranti, dati aggiornati dei luoghi e Google Maps richiedono ancora Internet. PizzaScan non passa automaticamente a un’IA cloud se l’analisi locale fallisce.',privacy:'Privacy e limiti nel dettaglio',privacyP:'Durante il download del modello, Hugging Face e i suoi server ricevono dati tecnici necessari, come indirizzo IP e file richiesti. La foto e la recensione non vengono inviate con la richiesta del modello. Foto e risultati restano locali in PizzaScan salvo esportazione, copia o condivisione esplicita.',limitsP:'CLIP e SigLIP sono modelli generali immagine-linguaggio, non valutatori certificati di pizza. Confrontano la foto con descrizioni in inglese per ciascuna categoria. Illuminazione, prospettiva, nitidezza, stile della pizza e bias appresi possono influenzare i risultati. Le cifre decimali non implicano tale precisione di misura e modelli diversi possono produrre punteggi diversi.',ownP:'La tua valutazione personale resta separata. Controlla sempre una bozza per Google Maps prima della pubblicazione e basa le affermazioni su gusto o servizio sulla tua esperienza reale. PizzaScan non pubblica mai recensioni automaticamente.',origin:'Nome e origine del modello',originP:'PizzaScan utilizza {model} di {dev} nella versione q8 ONNX ottimizzata da Xenova. L’esecuzione locale usa Transformers.js e ONNX Runtime. CLIP significa “Contrastive Language–Image Pre-training”; SigLIP “Sigmoid Loss for Language–Image Pre-training”.',source:'Fonte del modello:'},
 es:{selected:'MODELO OFFLINE SELECCIONADO',conversion:'Conversión ONNX de Xenova',download:'descarga adicional',device:'En tu dispositivo',noapi:'Análisis de foto sin clave API de IA',why:'¿Por qué se descarga un modelo?',whyP:'El modelo contiene patrones visuales y de texto ya aprendidos que PizzaScan usa para comparar la foto de tu pizza con descripciones. Así, el análisis puede ejecutarse en tu teléfono sin enviar la foto a un servicio de IA. Tus fotos no se utilizan para entrenar un modelo nuevo.',extra:'Además del APK:',extraP:'Los archivos del modelo no están incluidos en el APK. Solo después de tu confirmación PizzaScan descarga de Hugging Face el modelo seleccionado y lo guarda en el almacenamiento privado persistente de la app en este dispositivo. El mapa puede utilizarse sin un modelo.',disc:'Aviso sobre el análisis de fotos:',discP:'El índice experimental de IA de 0,1 a 10,0 estima características visibles y no es una medición fiable de calidad. El sabor, olor, temperatura, alérgenos, higiene y seguridad alimentaria no pueden determinarse a partir de la foto. Las 100 perspectivas son ponderaciones simuladas de los mismos 25 valores, no 100 expertos reales ni evaluaciones independientes.',dls:'Descarga, almacenamiento y costes',dlP:'La primera descarga de {model} ocupa aproximadamente {mb} MB, incluidos pequeños archivos auxiliares. El tamaño puede cambiar con nuevas versiones. Se recomienda Wi-Fi; los datos móviles pueden generar costes. PizzaScan no cobra por usar el modelo ni requiere suscripción de IA, cuenta del proveedor o clave API.',storeP:'Mantén libres varios cientos de MB además del espacio de la app. Cada modelo adicional requiere su propia descarga; los tres juntos ocupan unos 530 MB. La descarga y el análisis también requieren memoria de trabajo. La duración, batería y temperatura dependen del dispositivo. Puedes cancelar el proceso; los archivos almacenados completamente pueden reutilizarse.',offline:'¿Qué funciona sin conexión después?',offlineP:'Tras una descarga completa, el análisis de fotos funciona sin Internet. El modelo se guarda en el almacenamiento privado persistente de PizzaScan y se reutiliza tras reiniciar la app y después de una limpieza normal de caché. Cambiar a un modelo aún no instalado requiere otra descarga confirmada.',deleteP:'El modelo guardado solo se elimina al usar “Eliminar modelos descargados”, borrar los datos de PizzaScan en Android o desinstalar la app. Una limpieza normal de caché no elimina este almacenamiento persistente.',mapP:'“Sin conexión” se refiere al análisis de fotos. Nuevos mosaicos de mapa, búsquedas de restaurantes, datos actuales de lugares y Google Maps siguen necesitando Internet. PizzaScan no cambia silenciosamente a IA en la nube si falla el análisis local.',privacy:'Privacidad y límites en detalle',privacyP:'Durante la descarga del modelo, Hugging Face y sus servidores reciben datos técnicos necesarios, como tu dirección IP y los archivos solicitados. Tu foto y reseña no se envían con la solicitud del modelo. Las fotos y resultados permanecen locales en PizzaScan salvo que los exportes, copies o compartas explícitamente.',limitsP:'CLIP y SigLIP son modelos generales de imagen y lenguaje, no jueces certificados de pizza. Comparan la foto con descripciones en inglés para cada categoría. La iluminación, perspectiva, nitidez, estilo de pizza y sesgos aprendidos pueden afectar los resultados. Los decimales no implican esa precisión de medida y distintos modelos pueden dar puntuaciones diferentes.',ownP:'Tu valoración personal permanece separada. Revisa cualquier borrador para Google Maps antes de publicarlo y basa las afirmaciones sobre sabor o servicio en tu experiencia real. PizzaScan nunca publica una reseña automáticamente.',origin:'Nombre y origen del modelo',originP:'PizzaScan utiliza {model} de {dev} en la versión q8 ONNX optimizada por Xenova. La ejecución local usa Transformers.js y ONNX Runtime. CLIP significa “Contrastive Language–Image Pre-training”; SigLIP “Sigmoid Loss for Language–Image Pre-training”.',source:'Fuente del modelo:'},
 fr:{selected:'MODÈLE HORS LIGNE SÉLECTIONNÉ',conversion:'Conversion ONNX par Xenova',download:'téléchargement supplémentaire',device:'Sur votre appareil',noapi:'Analyse photo sans clé API IA',why:'Pourquoi un modèle est-il téléchargé ?',whyP:'Le modèle contient des schémas visuels et textuels déjà appris que PizzaScan utilise pour comparer votre photo de pizza à des descriptions. L’analyse peut ainsi s’exécuter sur votre téléphone sans envoyer la photo à un service d’IA. Vos photos ne servent pas à entraîner un nouveau modèle.',extra:'En plus de l’APK :',extraP:'Les fichiers du modèle ne sont pas inclus dans l’APK. Ce n’est qu’après votre confirmation que PizzaScan télécharge le modèle choisi depuis Hugging Face et l’enregistre dans le stockage privé persistant de l’application sur cet appareil. La carte reste utilisable sans modèle.',disc:'Avertissement sur l’analyse photo :',discP:'L’indice photo IA expérimental de 0,1 à 10,0 estime des caractéristiques visibles et ne constitue pas une mesure fiable de qualité. Le goût, l’odeur, la température, les allergènes, l’hygiène et la sécurité alimentaire ne peuvent pas être déterminés à partir de la photo. Les 100 perspectives sont des pondérations simulées des mêmes 25 valeurs, et non 100 experts réels ou évaluations indépendantes.',dls:'Téléchargement, stockage et coûts',dlP:'Le premier téléchargement de {model} représente environ {mb} Mo, petits fichiers annexes compris. La taille peut évoluer avec les versions du modèle. Le Wi-Fi est recommandé ; les données mobiles peuvent entraîner des frais. PizzaScan ne facture pas l’utilisation du modèle et ne nécessite ni abonnement IA, ni compte fournisseur, ni clé API.',storeP:'Conservez plusieurs centaines de Mo libres en plus de l’application. Chaque modèle supplémentaire nécessite son propre téléchargement ; les trois représentent environ 530 Mo. Le téléchargement et l’analyse nécessitent également de la mémoire vive. La durée, la batterie et la température dépendent de l’appareil. Vous pouvez annuler l’opération ; les fichiers complètement enregistrés peuvent être réutilisés.',offline:'Qu’est-ce qui fonctionne ensuite hors ligne ?',offlineP:'Après un téléchargement complet, l’analyse photo fonctionne sans Internet. Le modèle est enregistré dans le stockage privé persistant de PizzaScan et réutilisé après les redémarrages de l’application et après un nettoyage normal du cache. Passer à un modèle non encore installé nécessite un nouveau téléchargement confirmé.',deleteP:'Le modèle enregistré n’est supprimé que via « Supprimer les modèles téléchargés », en effaçant les données de PizzaScan dans Android ou en désinstallant l’application. Un nettoyage normal du cache ne supprime pas ce stockage persistant.',mapP:'« Hors ligne » concerne l’analyse photo. Les nouvelles tuiles de carte, les recherches de restaurants, les données actuelles des lieux et Google Maps nécessitent toujours Internet. PizzaScan ne bascule pas silencieusement vers une IA cloud si l’analyse locale échoue.',privacy:'Confidentialité et limites en détail',privacyP:'Lors du téléchargement du modèle, Hugging Face et ses serveurs reçoivent les données techniques nécessaires, telles que votre adresse IP et les fichiers demandés. Votre photo et votre avis ne sont pas envoyés avec la requête du modèle. Les photos et résultats restent locaux dans PizzaScan sauf exportation, copie ou partage explicite.',limitsP:'CLIP et SigLIP sont des modèles généraux image-langage, et non des experts certifiés en pizza. Ils comparent la photo à des descriptions en anglais pour chaque catégorie. L’éclairage, la perspective, la netteté, le style de pizza et les biais appris peuvent influencer les résultats. Les décimales n’impliquent pas ce niveau de précision et différents modèles peuvent produire des scores différents.',ownP:'Votre note personnelle reste séparée. Vérifiez tout brouillon Google Maps avant publication et fondez les affirmations sur le goût ou le service sur votre expérience réelle. PizzaScan ne publie jamais automatiquement un avis.',origin:'Nom et origine du modèle',originP:'PizzaScan utilise {model} de {dev} dans la version q8 ONNX optimisée par Xenova. L’exécution locale utilise Transformers.js et ONNX Runtime. CLIP signifie « Contrastive Language–Image Pre-training » ; SigLIP « Sigmoid Loss for Language–Image Pre-training ».',source:'Source du modèle :'}
};
function fill(s,m){return s.replaceAll('{model}',esc(m.fullName)).replaceAll('{dev}',esc(m.developer)).replaceAll('{mb}',String(m.downloadMB));}
function installModel(){if(!root.PizzaModelInfo||root.PizzaModelInfo.__fullI18n)return;const old=root.PizzaModelInfo.html;root.PizzaModelInfo.html=model=>{const l=I();if(l==='de')return old(model);const c=modelCopy[l];return `<div class="model-explanation"><div class="model-facts"><p class="eyebrow">${c.selected}</p><h2>${esc(model.fullName)}</h2><p>${esc(model.developer)} · ${c.conversion}</p><div class="model-fact-row"><span><strong>ca. ${model.downloadMB} MB</strong><small>${c.download}</small></span><span><strong>${c.device}</strong><small>${c.noapi}</small></span></div></div><h2>${c.why}</h2><p>${c.whyP}</p><p><strong>${c.extra}</strong> ${c.extraP}</p><p class="notice"><strong>${c.disc}</strong> ${c.discP}</p><details><summary>${c.dls}</summary><p>${fill(c.dlP,model)}</p><p>${c.storeP}</p></details><details><summary>${c.offline}</summary><p>${c.offlineP}</p><p>${c.deleteP}</p><p>${c.mapP}</p></details><details><summary>${c.privacy}</summary><p>${c.privacyP}</p><p>${c.limitsP}</p><p>${c.ownP}</p></details><details><summary>${c.origin}</summary><p>${fill(c.originP,model)}</p><p class="model-source">${c.source} <a href="https://huggingface.co/${esc(model.repo)}">${esc(model.repo)} ↗</a></p></details></div>`;};root.PizzaModelInfo.__fullI18n=true;}

const privacy={
 en:{kick:'PRIVACY',back:'Back to app',title:'PizzaScan Privacy Policy',date:'Updated: 12 September 2026 · Version 2.3.0 · Android package cloud.kosch.pizzascan',sections:[
 ['Controller and contact','PizzaScan is provided by Kolja Werner Schumann (KoSch), Germany. Contact is available via kosch.cloud and the public PizzaScan GitHub repository. Additional developer contact details are shown in the Google Play developer profile.'],
 ['Overview','PizzaScan provides a pizza and restaurant map, local photo analysis and a private review builder. No account or community is required. PizzaScan operates no advertising, analytics or tracking SDK and no developer server for user photos or reviews. Nothing is published automatically.'],
 ['Photos and local AI','You select a photo through Android’s document picker or camera. PizzaScan has no blanket access to your photo library. The image is resized locally and re-encoded as JPEG, which removes the original EXIF metadata. AI inference runs locally on your device and the photo is not uploaded for AI analysis or model training.','CLIP ViT-B/32, CLIP ViT-B/16 and SigLIP Base Patch16-224 are available as ONNX conversions by Xenova. After your confirmation, the selected model is downloaded from Hugging Face. Hugging Face and its delivery infrastructure receive technically necessary connection data such as IP address, time and requested model files, but not the photo or review text.'],
 ['Persistent model storage','After a successful first download, model files are stored in PizzaScan’s private persistent Android app storage. They are reused after app restarts and normal cache clearing. They are removed only when you explicitly remove downloaded models in PizzaScan, clear the app data in Android or uninstall the app.'],
 ['Map, restaurant search and location','Map tiles are loaded from OpenStreetMap. Restaurant data is requested from Overpass services and place/address search uses Photon. These external providers receive the requested map area, search terms or coordinates plus technically necessary connection data. Location access is optional, foreground-only and can be revoked in Android at any time. PizzaScan does not perform background tracking or build a movement profile.'],
 ['Reviews, clipboard and external apps','Your ratings, selected review building blocks and edited draft text are stored locally. The review builder uses your own statements and does not insert AI photo scores. Copying puts the displayed text on your system clipboard. Opening Google Maps is an explicit action; you choose the stars, paste or edit the text and publish it yourself. PizzaScan never publishes automatically.'],
 ['Local storage, export and deletion','Settings, saved places, ratings, analysis results and drafts are stored locally. JSON exports are saved only to the destination you choose in Android. If you choose cloud storage, that provider processes the exported file. Individual data can be deleted inside PizzaScan; all app data can be removed through Android app settings or by uninstalling PizzaScan. Android cloud backup for the app is disabled.'],
 ['Legal basis and security','Where the GDPR applies, processing is based on the function you request and, where required, your consent, for example for optional location access and model download. Network requests use HTTPS. Local data is protected by Android’s private app storage. External service providers may process connection data outside the EU/EEA according to their own privacy policies. PizzaScan contains no ads and does not sell personal data.'],
 ['Your rights','Subject to legal requirements, you may have rights of access, rectification, deletion, restriction, portability, objection and withdrawal of consent, and the right to complain to a competent data-protection authority. Data stored only on your device cannot be remotely inspected or deleted by the developer; the app and Android provide local deletion controls.'],
 ['Limits of photo analysis','The photo scores are experimental image-text comparisons. The 100 perspectives are simulated weighting profiles of the same 25 photo values, not real experts or independent assessments. Taste, smell, temperature, allergens, hygiene and food safety cannot be reliably determined from a photo. The app does not make legally significant automated decisions about people.']
 ]},
 it:{kick:'PRIVACY',back:'Torna all’app',title:'Informativa sulla privacy di PizzaScan',date:'Aggiornata: 12 settembre 2026 · Versione 2.3.0 · Pacchetto Android cloud.kosch.pizzascan',sections:[
 ['Titolare e contatti','PizzaScan è fornita da Kolja Werner Schumann (KoSch), Germania. È possibile contattarlo tramite kosch.cloud e il repository pubblico PizzaScan su GitHub. Ulteriori dati di contatto dello sviluppatore sono disponibili nel profilo sviluppatore di Google Play.'],
 ['Panoramica','PizzaScan offre una mappa di pizzerie e ristoranti, analisi foto locale e un generatore privato di recensioni. Non sono richiesti account o community. PizzaScan non gestisce pubblicità, SDK di analytics o tracciamento né server dello sviluppatore per foto o recensioni. Nulla viene pubblicato automaticamente.'],
 ['Foto e IA locale','La foto viene scelta tramite il selettore documenti di Android o la fotocamera. PizzaScan non ha accesso generale alla libreria fotografica. L’immagine viene ridimensionata localmente e ricodificata in JPEG, eliminando i metadati EXIF originali. L’inferenza IA avviene sul dispositivo e la foto non viene caricata per l’analisi o l’addestramento.','Sono disponibili CLIP ViT-B/32, CLIP ViT-B/16 e SigLIP Base Patch16-224 come conversioni ONNX di Xenova. Dopo la conferma, il modello selezionato viene scaricato da Hugging Face. Hugging Face e la relativa infrastruttura ricevono dati tecnici necessari, come indirizzo IP, orario e file richiesti, ma non la foto o il testo della recensione.'],
 ['Memoria persistente del modello','Dopo il primo download completato, i file del modello vengono salvati nella memoria privata persistente dell’app Android di PizzaScan. Vengono riutilizzati dopo il riavvio dell’app e dopo una normale pulizia della cache. Vengono rimossi solo tramite la funzione di rimozione dei modelli, cancellando i dati dell’app in Android o disinstallando PizzaScan.'],
 ['Mappa, ricerca ristoranti e posizione','Le tessere della mappa provengono da OpenStreetMap, i dati dei ristoranti da servizi Overpass e la ricerca di luoghi/indirizzi da Photon. Questi fornitori ricevono l’area richiesta, i termini di ricerca o le coordinate e i dati tecnici di connessione. L’accesso alla posizione è facoltativo, solo in primo piano e revocabile in Android. PizzaScan non effettua tracciamento in background né crea profili di movimento.'],
 ['Recensioni, appunti e app esterne','Valutazioni, elementi scelti e bozze vengono salvati localmente. Il generatore usa le tue dichiarazioni e non inserisce punteggi IA della foto. La copia inserisce il testo negli appunti di sistema. L’apertura di Google Maps è volontaria: scegli le stelle, modifichi il testo e pubblichi personalmente. PizzaScan non pubblica automaticamente.'],
 ['Memoria locale, esportazione e cancellazione','Impostazioni, luoghi salvati, valutazioni, risultati e bozze restano sul dispositivo. Le esportazioni JSON vengono salvate solo nella destinazione scelta in Android; scegliendo un cloud, quel fornitore tratta il file. I singoli dati possono essere eliminati in PizzaScan; tutti i dati dell’app tramite le impostazioni Android o la disinstallazione. Il backup cloud Android dell’app è disattivato.'],
 ['Base giuridica e sicurezza','Quando si applica il GDPR, il trattamento si basa sulla funzione richiesta e, quando necessario, sul consenso, ad esempio per posizione facoltativa e download del modello. Le richieste di rete usano HTTPS. I dati locali sono protetti dalla memoria privata dell’app Android. I servizi esterni possono trattare dati di connessione fuori UE/SEE secondo le proprie informative. PizzaScan non contiene pubblicità e non vende dati personali.'],
 ['I tuoi diritti','In presenza dei requisiti legali puoi avere diritti di accesso, rettifica, cancellazione, limitazione, portabilità, opposizione e revoca del consenso, oltre al diritto di reclamo presso un’autorità di controllo. I dati solo locali non possono essere visualizzati o cancellati a distanza dallo sviluppatore; l’app e Android forniscono i controlli di cancellazione.'],
 ['Limiti dell’analisi foto','I punteggi sono confronti sperimentali immagine-testo. Le 100 prospettive sono profili simulati di ponderazione degli stessi 25 valori, non esperti reali o valutazioni indipendenti. Gusto, odore, temperatura, allergeni, igiene e sicurezza alimentare non possono essere determinati in modo affidabile da una foto.']
 ]},
 es:{kick:'PRIVACIDAD',back:'Volver a la app',title:'Política de privacidad de PizzaScan',date:'Actualizada: 12 de septiembre de 2026 · Versión 2.3.0 · Paquete Android cloud.kosch.pizzascan',sections:[
 ['Responsable y contacto','PizzaScan es ofrecida por Kolja Werner Schumann (KoSch), Alemania. Puedes contactar a través de kosch.cloud y del repositorio público de PizzaScan en GitHub. El perfil de desarrollador de Google Play contiene datos de contacto adicionales.'],
 ['Resumen','PizzaScan ofrece un mapa de pizzerías y restaurantes, análisis local de fotos y un generador privado de reseñas. No se requiere cuenta ni comunidad. PizzaScan no opera publicidad, SDK de analítica o seguimiento ni un servidor del desarrollador para fotos o reseñas. Nada se publica automáticamente.'],
 ['Fotos e IA local','Seleccionas una foto mediante el selector de documentos de Android o la cámara. PizzaScan no tiene acceso general a tu galería. La imagen se redimensiona localmente y se vuelve a codificar como JPEG, eliminando los metadatos EXIF originales. La inferencia de IA se ejecuta en el dispositivo y la foto no se sube para análisis ni entrenamiento.','Están disponibles CLIP ViT-B/32, CLIP ViT-B/16 y SigLIP Base Patch16-224 como conversiones ONNX de Xenova. Tras tu confirmación, el modelo elegido se descarga desde Hugging Face. Hugging Face y su infraestructura reciben los datos técnicos necesarios, como dirección IP, hora y archivos solicitados, pero no la foto ni el texto de la reseña.'],
 ['Almacenamiento persistente del modelo','Tras completar la primera descarga, los archivos del modelo se guardan en el almacenamiento privado persistente de la app Android de PizzaScan. Se reutilizan después de reiniciar la app y de una limpieza normal de caché. Solo se eliminan al usar la opción de eliminar modelos, borrar los datos de la app en Android o desinstalar PizzaScan.'],
 ['Mapa, búsqueda y ubicación','Los mosaicos del mapa proceden de OpenStreetMap, los datos de restaurantes de servicios Overpass y la búsqueda de lugares/direcciones de Photon. Estos proveedores reciben el área solicitada, términos de búsqueda o coordenadas y datos técnicos de conexión. El acceso a la ubicación es opcional, solo en primer plano y revocable en Android. PizzaScan no hace seguimiento en segundo plano ni crea perfiles de movimiento.'],
 ['Reseñas, portapapeles y apps externas','Tus valoraciones, elementos seleccionados y borradores se guardan localmente. El generador utiliza tus propias afirmaciones y no inserta puntuaciones de la IA de la foto. Copiar coloca el texto en el portapapeles del sistema. Abrir Google Maps es una acción voluntaria: tú eliges estrellas, editas el texto y publicas. PizzaScan nunca publica automáticamente.'],
 ['Almacenamiento, exportación y borrado','Ajustes, lugares guardados, valoraciones, resultados y borradores permanecen en el dispositivo. Las exportaciones JSON solo se guardan en el destino elegido en Android; si eliges nube, ese proveedor procesa el archivo. Los datos individuales pueden eliminarse en PizzaScan y todos los datos desde los ajustes de Android o desinstalando la app. La copia de seguridad en la nube de Android está desactivada.'],
 ['Base jurídica y seguridad','Cuando se aplica el RGPD, el tratamiento se basa en la función solicitada y, cuando corresponde, en tu consentimiento, por ejemplo para ubicación opcional y descarga del modelo. Las solicitudes de red usan HTTPS. Los datos locales están protegidos por el almacenamiento privado de Android. Proveedores externos pueden tratar datos de conexión fuera de la UE/EEE según sus políticas. PizzaScan no contiene anuncios ni vende datos personales.'],
 ['Tus derechos','Cuando se cumplan los requisitos legales puedes tener derechos de acceso, rectificación, supresión, limitación, portabilidad, oposición y retirada del consentimiento, además del derecho a reclamar ante una autoridad de protección de datos. Los datos exclusivamente locales no pueden ser vistos o borrados de forma remota por el desarrollador; la app y Android proporcionan controles de borrado.'],
 ['Límites del análisis de fotos','Las puntuaciones son comparaciones experimentales imagen-texto. Las 100 perspectivas son perfiles simulados de ponderación de los mismos 25 valores, no expertos reales ni evaluaciones independientes. El sabor, olor, temperatura, alérgenos, higiene y seguridad alimentaria no pueden determinarse de forma fiable a partir de una foto.']
 ]},
 fr:{kick:'CONFIDENTIALITÉ',back:'Retour à l’application',title:'Politique de confidentialité de PizzaScan',date:'Mise à jour : 12 septembre 2026 · Version 2.3.0 · Package Android cloud.kosch.pizzascan',sections:[
 ['Responsable et contact','PizzaScan est proposée par Kolja Werner Schumann (KoSch), Allemagne. Le contact est possible via kosch.cloud et le dépôt public PizzaScan sur GitHub. Des coordonnées supplémentaires figurent dans le profil développeur Google Play.'],
 ['Vue d’ensemble','PizzaScan propose une carte de pizzerias et restaurants, une analyse photo locale et un générateur privé d’avis. Aucun compte ni aucune communauté n’est requis. PizzaScan n’exploite ni publicité, ni SDK d’analytics ou de suivi, ni serveur développeur pour les photos ou avis. Rien n’est publié automatiquement.'],
 ['Photos et IA locale','Vous choisissez une photo via le sélecteur de documents Android ou l’appareil photo. PizzaScan n’a pas d’accès général à votre photothèque. L’image est redimensionnée localement puis réencodée en JPEG, ce qui supprime les métadonnées EXIF d’origine. L’inférence IA s’exécute sur l’appareil et la photo n’est pas envoyée pour analyse ou entraînement.','CLIP ViT-B/32, CLIP ViT-B/16 et SigLIP Base Patch16-224 sont disponibles sous forme de conversions ONNX par Xenova. Après votre confirmation, le modèle choisi est téléchargé depuis Hugging Face. Hugging Face et son infrastructure reçoivent les données techniques nécessaires, comme l’adresse IP, l’heure et les fichiers demandés, mais pas la photo ni le texte de l’avis.'],
 ['Stockage persistant du modèle','Après le premier téléchargement complet, les fichiers du modèle sont enregistrés dans le stockage privé persistant de l’application Android PizzaScan. Ils sont réutilisés après les redémarrages et après un nettoyage normal du cache. Ils ne sont supprimés qu’en utilisant la fonction de suppression des modèles, en effaçant les données de l’application dans Android ou en désinstallant PizzaScan.'],
 ['Carte, recherche et localisation','Les tuiles de carte proviennent d’OpenStreetMap, les données de restaurants de services Overpass et la recherche de lieux/adresses de Photon. Ces fournisseurs reçoivent la zone demandée, les termes de recherche ou coordonnées ainsi que les données techniques de connexion. L’accès à la localisation est facultatif, uniquement au premier plan et révocable dans Android. PizzaScan n’effectue aucun suivi en arrière-plan ni profil de déplacement.'],
 ['Avis, presse-papiers et applications externes','Vos notes, éléments sélectionnés et brouillons sont enregistrés localement. Le générateur utilise vos propres déclarations et n’insère pas les scores IA de la photo. Copier place le texte dans le presse-papiers système. Ouvrir Google Maps est une action volontaire : vous choisissez les étoiles, modifiez le texte et publiez vous-même. PizzaScan ne publie jamais automatiquement.'],
 ['Stockage, exportation et suppression','Paramètres, lieux enregistrés, notes, résultats et brouillons restent sur l’appareil. Les exports JSON sont enregistrés uniquement à l’emplacement choisi dans Android ; si vous choisissez un cloud, ce fournisseur traite le fichier. Les données individuelles peuvent être supprimées dans PizzaScan, et toutes les données via les paramètres Android ou la désinstallation. La sauvegarde cloud Android de l’application est désactivée.'],
 ['Base juridique et sécurité','Lorsque le RGPD s’applique, le traitement repose sur la fonction demandée et, lorsque nécessaire, sur votre consentement, par exemple pour la localisation facultative et le téléchargement du modèle. Les requêtes réseau utilisent HTTPS. Les données locales sont protégées par le stockage privé Android. Des fournisseurs externes peuvent traiter des données de connexion hors UE/EEE selon leurs propres politiques. PizzaScan ne contient pas de publicité et ne vend pas de données personnelles.'],
 ['Vos droits','Sous réserve des conditions légales, vous pouvez disposer de droits d’accès, rectification, effacement, limitation, portabilité, opposition et retrait du consentement, ainsi que du droit de saisir une autorité de protection des données. Les données exclusivement locales ne peuvent pas être consultées ou supprimées à distance par le développeur ; l’application et Android fournissent les contrôles de suppression.'],
 ['Limites de l’analyse photo','Les scores sont des comparaisons expérimentales image-texte. Les 100 perspectives sont des profils simulés de pondération des mêmes 25 valeurs, et non des experts réels ou évaluations indépendantes. Le goût, l’odeur, la température, les allergènes, l’hygiène et la sécurité alimentaire ne peuvent pas être déterminés de manière fiable à partir d’une photo.']
 ]}
};
